import{_ as r,C as s,o as a,c as o,a2 as e,b as c,w as d,a as i,E as l,a3 as v}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Protection Plus","description":"Kernel-level abuse protection & antivirus for container hosts — detects and stops miners, outbound DDoS, port scans, zip bombs, exploits, Tor/proxy abuse and malware, then alerts and enforces automatically.","frontmatter":{"title":"Protection Plus","description":"Kernel-level abuse protection & antivirus for container hosts — detects and stops miners, outbound DDoS, port scans, zip bombs, exploits, Tor/proxy abuse and malware, then alerts and enforces automatically.","head":[["meta",{"name":"og:title","content":"Protection Plus — Container-Host Abuse Protection & Antivirus"}],["meta",{"name":"og:description","content":"One static Go binary that guards Pterodactyl/Docker/VPS hosts against miners, DDoS, port scans, zip bombs, exploits, Tor/proxy abuse and malware. Detects, alerts, and enforces."}]]},"headers":[],"relativePath":"protection/index.md","filePath":"protection/index.md","lastUpdated":1787470737000}'),h={name:"protection/index.md"};function p(g,t,u,y,b,m){const n=s("Mermaid");return a(),o("div",null,[t[1]||(t[1]=e(`<h1 id="protection-plus" tabindex="-1" data-v-7869744c>Protection Plus <a class="header-anchor" href="#protection-plus" aria-label="Permalink to &quot;Protection Plus&quot;" data-v-7869744c>​</a></h1><p data-v-7869744c><strong data-v-7869744c>Kernel-level abuse protection &amp; antivirus for container hosts</strong> — a single static Go binary that guards Pterodactyl/Wings nodes, generic Docker hosts and bare VPS boxes against the things that keep hosting operators awake at night.</p><p data-v-7869744c>It watches every process, connection, container, archive and uploaded file on the host, and when it finds a real threat it <strong data-v-7869744c>alerts</strong> (Discord, email, webhook) and <strong data-v-7869744c>enforces</strong> (kill container, suspend the Pterodactyl server, quarantine the file, kill the process) — all driven by a simple, overridable rule set.</p><div class="tip custom-block" style="margin-top:1.5rem;" data-v-7869744c><p data-v-7869744c><strong data-v-7869744c>🛡️ Built for ALTIS TECH SOLUTIONS by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer" data-v-7869744c>AnAverageBeing</a></strong><br data-v-7869744c><a href="https://github.com/AnAverageBeing/protection" target="_blank" rel="noreferrer" data-v-7869744c>GitHub Repo</a> · <code data-v-7869744c>MIT License</code> · runs as the system command <code data-v-7869744c>protection</code></p></div><hr data-v-7869744c><h2 id="what-it-protects-against" tabindex="-1" data-v-7869744c>What it protects against <a class="header-anchor" href="#what-it-protects-against" aria-label="Permalink to &quot;What it protects against&quot;" data-v-7869744c>​</a></h2><p data-v-7869744c>Ten independent detector modules — delete a block from the config (or set <code data-v-7869744c>enabled: false</code>) and that feature disappears completely.</p><table tabindex="0" data-v-7869744c><thead data-v-7869744c><tr data-v-7869744c><th data-v-7869744c>Threat</th><th data-v-7869744c>What it catches</th></tr></thead><tbody data-v-7869744c><tr data-v-7869744c><td data-v-7869744c>⛏️ <strong data-v-7869744c>Cryptocurrency miners</strong></td><td data-v-7869744c>Known miner binaries, miner argument fingerprints (<code data-v-7869744c>stratum+tcp</code>, <code data-v-7869744c>--donate-level</code>…), sustained high CPU (even <em data-v-7869744c>unknown</em> miners), connections to mining-pool ports, and masked (deleted-on-disk) binaries</td></tr><tr data-v-7869744c><td data-v-7869744c>🌊 <strong data-v-7869744c>Outbound DDoS / stress tools</strong></td><td data-v-7869744c>Per-container egress flood rates (pps/bps via docker stats), known tools (hping3, t50, mhddos, LOIC/HOIC…), <code data-v-7869744c>java -jar *ddos.jar</code> flooders, and per-process connection floods</td></tr><tr data-v-7869744c><td data-v-7869744c>🔭 <strong data-v-7869744c>Port scans</strong></td><td data-v-7869744c>Half-open (<code data-v-7869744c>SYN_SENT</code>) connection fan-out across many ports/hosts in a sliding window, plus scanner binaries (nmap, masscan, zmap, rustscan…)</td></tr><tr data-v-7869744c><td data-v-7869744c>💣 <strong data-v-7869744c>Decompression bombs</strong></td><td data-v-7869744c>zip / jar / tar / gzip / xz / bzip2 / 7z / rar bombs detected from archive metadata <strong data-v-7869744c>without extracting</strong> — caught mid-extraction by an event-driven hot trigger <em data-v-7869744c>and</em> on disk by a periodic sweep</td></tr><tr data-v-7869744c><td data-v-7869744c>🐚 <strong data-v-7869744c>Exploits &amp; container escapes</strong></td><td data-v-7869744c>Privesc/exploit tools (pwnkit, dirtypipe, linpeas…), network-bound reverse shells, privilege escalation, <code data-v-7869744c>nsenter</code> namespace breakout, and setuid payloads dropped in world-writable dirs</td></tr><tr data-v-7869744c><td data-v-7869744c>🧅 <strong data-v-7869744c>Tor / proxy / VPN abuse</strong></td><td data-v-7869744c>Tor exits &amp; relays, proxy/VPN tunnels (OpenVPN, WireGuard, Shadowsocks, v2ray/xray, trojan, hysteria, sing-box, ngrok, frp…), customer mail servers, IRC bots, listeners on Tor/SOCKS/proxy ports, and executables launched from user upload dirs</td></tr><tr data-v-7869744c><td data-v-7869744c>🦠 <strong data-v-7869744c>Malware (on-access antivirus)</strong></td><td data-v-7869744c>fsnotify watches upload dirs and scans every file the moment it is closed after writing — SHA-256 against the MalwareBazaar hash blocklist, then YARA against the curated rule bundle. Hits map to the <code data-v-7869744c>malware</code> rule (quarantine + alert by default)</td></tr><tr data-v-7869744c><td data-v-7869744c>🧬 <strong data-v-7869744c>YARA sweeps</strong></td><td data-v-7869744c>Periodic full-tree YARA scan of your scan paths via the <code data-v-7869744c>yara</code> CLI — the backstop to the on-access hot path (disabled by default)</td></tr><tr data-v-7869744c><td data-v-7869744c>🩹 <strong data-v-7869744c>Tampering (FIM)</strong></td><td data-v-7869744c>File-integrity monitoring: alerts when the daemon&#39;s own binary, its config, or any listed path changes on disk — catches attackers tampering with Protection itself</td></tr><tr data-v-7869744c><td data-v-7869744c>🧪 <strong data-v-7869744c>Vulnerable images</strong></td><td data-v-7869744c>Container-image vulnerability scanning via the <code data-v-7869744c>trivy</code> CLI — one alert per image with HIGH/CRITICAL counts and the top CVEs (disabled by default, alert-only)</td></tr></tbody></table><hr data-v-7869744c><h2 id="quick-install" tabindex="-1" data-v-7869744c>Quick install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick install&quot;" data-v-7869744c>​</a></h2><div class="language-bash vp-adaptive-theme" data-v-7869744c><button title="Copy Code" class="copy" data-v-7869744c></button><span class="lang" data-v-7869744c>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-7869744c><code data-v-7869744c><span class="line" data-v-7869744c><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-7869744c>curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-7869744c> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-7869744c> https://raw.githubusercontent.com/AnAverageBeing/protection/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" data-v-7869744c> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-7869744c> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-7869744c> bash</span></span></code></pre></div><p data-v-7869744c>The installer downloads the prebuilt static binary for your architecture, installs the systemd service, then <strong data-v-7869744c>asks a few quick questions</strong> (installation name, what to protect, Discord webhook, Pterodactyl auto-suspend, scan directories) and writes a config in safe <strong data-v-7869744c>dry-run mode</strong>. No Go toolchain, no dependencies.</p><p data-v-7869744c>After installing, pull the threat intel once so the antivirus layer is fully armed, and take a look at what the daemon sees:</p><div class="language-bash vp-adaptive-theme" data-v-7869744c><button title="Copy Code" class="copy" data-v-7869744c></button><span class="lang" data-v-7869744c>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-7869744c><code data-v-7869744c><span class="line" data-v-7869744c><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-7869744c>sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-7869744c> protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-7869744c> rules</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-7869744c> update</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;" data-v-7869744c>   # YARA rule bundle + SHA-256 malware blocklist</span></span>
<span class="line" data-v-7869744c><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-7869744c>sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-7869744c> protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-7869744c> scan</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;" data-v-7869744c>           # one-shot recon: every detector, no actions taken</span></span></code></pre></div><div class="tip custom-block" data-v-7869744c><p class="custom-block-title" data-v-7869744c>START IN DRY-RUN</p><p data-v-7869744c>Protection ships with <code data-v-7869744c>dry_run: true</code>. It detects and alerts but won&#39;t take destructive action until <em data-v-7869744c>you</em> arm it. Watch the alerts for a day, tune thresholds, then flip <code data-v-7869744c>dry_run: false</code> and restart. See <a href="./getting-started/quick-start" data-v-7869744c>Quick Start</a>.</p></div><hr data-v-7869744c><h2 id="the-antivirus-layer" tabindex="-1" data-v-7869744c>The antivirus layer <a class="header-anchor" href="#the-antivirus-layer" aria-label="Permalink to &quot;The antivirus layer&quot;" data-v-7869744c>​</a></h2><p data-v-7869744c>Beyond behavioral abuse detection, Protection Plus v1.0.0 ships a real antivirus pipeline for user uploads:</p><ul data-v-7869744c><li data-v-7869744c><strong data-v-7869744c>On-access scanning.</strong> A single recursive fsnotify watcher covers your upload trees; every file is scanned the moment it is closed after writing (debounced ~500 ms so editors and downloaders writing in bursts don&#39;t misfire).</li><li data-v-7869744c><strong data-v-7869744c>SHA-256 blocklist.</strong> Files are hashed against the MalwareBazaar SHA-256 export held in memory — a hit is <strong data-v-7869744c>critical</strong>.</li><li data-v-7869744c><strong data-v-7869744c>Curated YARA rules.</strong> Files are then matched against the project&#39;s curated rule bundle (webshells, miners, Tor, Mirai, IRC bots, Linux backdoors, privesc exploits, crypto stealers) via the <code data-v-7869744c>yara</code> CLI — a hit is <strong data-v-7869744c>high</strong>.</li><li data-v-7869744c><strong data-v-7869744c>Intel management.</strong> <code data-v-7869744c>protection rules update</code> downloads the rule bundle and hash blocklist atomically (temp file + rename), merges your <code data-v-7869744c>custom_hashlist</code>, and the daemon auto-refreshes every 24 h. Point <code data-v-7869744c>intel.rules_url</code> at your own URL to self-host.</li></ul><p data-v-7869744c>Matched files land in the <code data-v-7869744c>malware</code> category, which the default policy quarantines (moved aside, <code data-v-7869744c>chmod 000</code> — evidence preserved) and alerts on.</p><hr data-v-7869744c><h2 id="why-protection-plus" tabindex="-1" data-v-7869744c>Why Protection Plus? <a class="header-anchor" href="#why-protection-plus" aria-label="Permalink to &quot;Why Protection Plus?&quot;" data-v-7869744c>​</a></h2><p data-v-7869744c>A Pterodactyl/Docker node hands semi-trusted strangers the ability to run arbitrary code. One bad tenant can mine Monero on your CPUs, launch a DDoS that gets your IP null-routed, run a Tor exit on your bandwidth, upload a webshell through the panel, drop a zip bomb that fills your disk, or attempt a container escape. Protection Plus is the watchdog that sits on the host — <strong data-v-7869744c>outside</strong> every container — and shuts that down before it becomes your problem.</p><table tabindex="0" data-v-7869744c><thead data-v-7869744c><tr data-v-7869744c><th data-v-7869744c>Approach</th><th data-v-7869744c>Pain point</th></tr></thead><tbody data-v-7869744c><tr data-v-7869744c><td data-v-7869744c><strong data-v-7869744c>Manual <code data-v-7869744c>htop</code> + luck</strong></td><td data-v-7869744c>You find out when the abuse report or the null-route arrives</td></tr><tr data-v-7869744c><td data-v-7869744c><strong data-v-7869744c>In-container agents</strong></td><td data-v-7869744c>Tenants can see, kill, or evade anything inside their own container</td></tr><tr data-v-7869744c><td data-v-7869744c><strong data-v-7869744c>Generic host IDS (e.g. fail2ban)</strong></td><td data-v-7869744c>Log-based, reactive, no container attribution, no miner/zip-bomb/malware concept</td></tr><tr data-v-7869744c><td data-v-7869744c><strong data-v-7869744c>Cloud &quot;container security&quot; SaaS</strong></td><td data-v-7869744c>Expensive, closed-source, heavy, overkill for a game-hosting node</td></tr></tbody></table><p data-v-7869744c>Protection Plus fills the gap with a <strong data-v-7869744c>single static binary</strong>, <code data-v-7869744c>/proc</code> + the Docker socket, and a security-first default policy.</p><hr data-v-7869744c><h2 id="architecture-at-a-glance" tabindex="-1" data-v-7869744c>Architecture at a glance <a class="header-anchor" href="#architecture-at-a-glance" aria-label="Permalink to &quot;Architecture at a glance&quot;" data-v-7869744c>​</a></h2>`,27)),(a(),c(v,null,{default:d(()=>[l(n,{id:"mermaid-224",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20SRC%5B%22%2Fproc%20%2B%20Docker%20socket%3Cbr%2F%3E(host%20%26%20every%20container%20netns)%22%5D%20--%3E%20SNAP%5BSystem%20Snapshot%3Cbr%2F%3Eone%20capture%20per%20tick%5D%0A%20%20%20%20FS%5B%22fsnotify%3Cbr%2F%3E(upload%20dirs)%22%5D%20--%3E%20OA%5Bonaccess%5D%0A%0A%20%20%20%20SNAP%20--%3E%20M%5Bminer%5D%0A%20%20%20%20SNAP%20--%3E%20P%5Bportscan%5D%0A%20%20%20%20SNAP%20--%3E%20D%5Bddos%5D%0A%20%20%20%20SNAP%20--%3E%20Z%5Bzipbomb%5D%0A%20%20%20%20SNAP%20--%3E%20E%5Bexploit%5D%0A%20%20%20%20SNAP%20--%3E%20A%5Babuse%5D%0A%20%20%20%20SNAP%20--%3E%20Y%5Byara%5D%0A%20%20%20%20SNAP%20--%3E%20F%5Bfim%5D%0A%20%20%20%20SNAP%20--%3E%20T%5Btrivy%5D%0A%0A%20%20%20%20INTEL%5B%22protection%20rules%20update%3Cbr%2F%3EYARA%20bundle%20%2B%20SHA-256%20blocklist%22%5D%20--%3E%20OA%0A%20%20%20%20INTEL%20--%3E%20Y%0A%0A%20%20%20%20M%20--%3E%20EV%5BEvents%5D%0A%20%20%20%20P%20--%3E%20EV%0A%20%20%20%20D%20--%3E%20EV%0A%20%20%20%20Z%20--%3E%20EV%0A%20%20%20%20E%20--%3E%20EV%0A%20%20%20%20A%20--%3E%20EV%0A%20%20%20%20Y%20--%3E%20EV%0A%20%20%20%20F%20--%3E%20EV%0A%20%20%20%20T%20--%3E%20EV%0A%20%20%20%20OA%20--%3E%20EV%0A%0A%20%20%20%20EV%20--%3E%20ENG%5BEngine%3Cbr%2F%3Escope%20%2B%20whitelist%20%2B%20dedup%20%2B%20cooldown%5D%0A%20%20%20%20ENG%20--%3E%20RULES%7BRule%20match%3Cbr%2F%3Ecategory%20%2B%20severity%7D%0A%20%20%20%20RULES%20--%3E%7Calert%7C%20AL%5BDiscord%20%C2%B7%20SMTP%20%C2%B7%20Webhook%3Cbr%2F%3E%2B%20batching%5D%0A%20%20%20%20RULES%20--%3E%7Cenforce%7C%20AC%5Bneutralize%20%C2%B7%20suspend_server%3Cbr%2F%3Equarantine_file%20%C2%B7%20kill_process%5D%0A"})]),fallback:d(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<p data-v-7869744c>Every detector reads from one shared per-tick snapshot, emits <code data-v-7869744c>Event</code>s, and the engine matches them against your rules to decide what to alert and what to enforce. The on-access scanner runs event-driven alongside the tick loop, fed by the same intel the periodic YARA sweep uses.</p><hr data-v-7869744c><h2 id="key-features" tabindex="-1" data-v-7869744c>Key features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key features&quot;" data-v-7869744c>​</a></h2><ul data-v-7869744c><li data-v-7869744c><strong data-v-7869744c>Single static binary, zero cgo.</strong> Drop it on any Linux amd64/arm64 node — the only build dependency is <code data-v-7869744c>gopkg.in/yaml.v3</code>.</li><li data-v-7869744c><strong data-v-7869744c>No agents inside containers.</strong> Watches from the host, so tenants can&#39;t see, disable, or evade it.</li><li data-v-7869744c><strong data-v-7869744c>Full container network visibility.</strong> Reads each container&#39;s network namespace directly, so a miner phoning a pool or a scan launched <em data-v-7869744c>inside</em> a container is seen and attributed to that container.</li><li data-v-7869744c><strong data-v-7869744c>Antivirus built in.</strong> fsnotify on-access scanning of uploads, a SHA-256 MalwareBazaar blocklist, and a curated YARA bundle — managed with <code data-v-7869744c>protection rules update</code> and a 24 h auto-refresh.</li><li data-v-7869744c><strong data-v-7869744c>Works on bare VPS too.</strong> The smart <code data-v-7869744c>neutralize</code> action kills the <em data-v-7869744c>container</em> for container threats and the <em data-v-7869744c>process</em> for host threats — one policy, every host type.</li><li data-v-7869744c><strong data-v-7869744c>Event-driven, not just polled.</strong> A CPU + disk-write spike (an active extraction) instantly triggers a targeted zip-bomb check; uploads are scanned the moment they land — no waiting for the next sweep.</li><li data-v-7869744c><strong data-v-7869744c>Pterodactyl-native.</strong> Maps offending containers and volume files back to the owning server UUID and can suspend the server via the Application API.</li><li data-v-7869744c><strong data-v-7869744c>Beautiful alerts, without the flood.</strong> Markdown-formatted Discord embeds, plus SMTP and generic JSON webhooks — each with its own minimum-severity gate, plus optional <strong data-v-7869744c>alert batching</strong> that collapses a burst into one digest alert.</li><li data-v-7869744c><strong data-v-7869744c>Whitelisting.</strong> Trusted paths are never scanned or flagged; trusted containers (full ID, short ID, or name) are never flagged, killed, or suspended — checked before rules ever see an event.</li><li data-v-7869744c><strong data-v-7869744c>Self-healing under systemd.</strong> The unit runs with <code data-v-7869744c>WatchdogSec=60s</code>; the daemon pets the watchdog after every scan tick via pure-Go <code data-v-7869744c>sd_notify</code>, so a hung detection loop gets killed and restarted automatically.</li><li data-v-7869744c><strong data-v-7869744c>Measured footprint.</strong> ~13 MB RSS and ~1–3% CPU at the default 5 s interval on live nodes — and a synthetic <strong data-v-7869744c>104K pps</strong> outbound flood from inside a container was detected and attributed to that container.</li><li data-v-7869744c><strong data-v-7869744c>Safe by default &amp; fully tunable.</strong> Ships in dry-run; every threshold, signature list and rule lives in one documented YAML file.</li></ul><hr data-v-7869744c><h2 id="modes" tabindex="-1" data-v-7869744c>Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;" data-v-7869744c>​</a></h2><p data-v-7869744c>Set <code data-v-7869744c>general.mode</code> (or pick it in the installer) to scope what Protection Plus acts on:</p><table tabindex="0" data-v-7869744c><thead data-v-7869744c><tr data-v-7869744c><th data-v-7869744c>Mode</th><th data-v-7869744c>Scope</th></tr></thead><tbody data-v-7869744c><tr data-v-7869744c><td data-v-7869744c><code data-v-7869744c>server</code></td><td data-v-7869744c>Host/VPS processes only — great for a plain VPS</td></tr><tr data-v-7869744c><td data-v-7869744c><code data-v-7869744c>docker</code></td><td data-v-7869744c>Containerised threats only — Pterodactyl/Docker nodes</td></tr><tr data-v-7869744c><td data-v-7869744c><code data-v-7869744c>both</code></td><td data-v-7869744c>Everything (default)</td></tr></tbody></table><hr data-v-7869744c><h2 id="comparison" tabindex="-1" data-v-7869744c>Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;" data-v-7869744c>​</a></h2><table tabindex="0" data-v-7869744c><thead data-v-7869744c><tr data-v-7869744c><th data-v-7869744c>Capability</th><th style="text-align:center;" data-v-7869744c>Protection Plus</th><th style="text-align:center;" data-v-7869744c>fail2ban</th><th style="text-align:center;" data-v-7869744c>In-container agent</th><th style="text-align:center;" data-v-7869744c>Cloud SaaS</th></tr></thead><tbody data-v-7869744c><tr data-v-7869744c><td data-v-7869744c>Miner detection (CPU + pool + signature)</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>❌</td><td style="text-align:center;" data-v-7869744c>⚠️</td><td style="text-align:center;" data-v-7869744c>✅</td></tr><tr data-v-7869744c><td data-v-7869744c>Outbound DDoS detection</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>❌</td><td style="text-align:center;" data-v-7869744c>⚠️</td><td style="text-align:center;" data-v-7869744c>✅</td></tr><tr data-v-7869744c><td data-v-7869744c>Zip-bomb detection (no extract)</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>❌</td><td style="text-align:center;" data-v-7869744c>❌</td><td style="text-align:center;" data-v-7869744c>⚠️</td></tr><tr data-v-7869744c><td data-v-7869744c>Container escape / reverse shell</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>❌</td><td style="text-align:center;" data-v-7869744c>⚠️</td><td style="text-align:center;" data-v-7869744c>✅</td></tr><tr data-v-7869744c><td data-v-7869744c>Tor / proxy / VPN abuse detection</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>❌</td><td style="text-align:center;" data-v-7869744c>⚠️</td><td style="text-align:center;" data-v-7869744c>⚠️</td></tr><tr data-v-7869744c><td data-v-7869744c>On-access malware scanning (hash + YARA)</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>❌</td><td style="text-align:center;" data-v-7869744c>⚠️</td><td style="text-align:center;" data-v-7869744c>✅</td></tr><tr data-v-7869744c><td data-v-7869744c>Self-tamper monitoring (FIM) + watchdog</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>❌</td><td style="text-align:center;" data-v-7869744c>❌</td><td style="text-align:center;" data-v-7869744c>⚠️</td></tr><tr data-v-7869744c><td data-v-7869744c>Container network visibility (per-netns)</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>❌</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>✅</td></tr><tr data-v-7869744c><td data-v-7869744c>Tenant-evasion resistant (host-side)</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>❌</td><td style="text-align:center;" data-v-7869744c>✅</td></tr><tr data-v-7869744c><td data-v-7869744c>Pterodactyl auto-suspend</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>❌</td><td style="text-align:center;" data-v-7869744c>❌</td><td style="text-align:center;" data-v-7869744c>❌</td></tr><tr data-v-7869744c><td data-v-7869744c>Single static binary, no deps</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>⚠️</td><td style="text-align:center;" data-v-7869744c>❌</td><td style="text-align:center;" data-v-7869744c>❌</td></tr><tr data-v-7869744c><td data-v-7869744c>Open source / self-hosted</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>✅</td><td style="text-align:center;" data-v-7869744c>varies</td><td style="text-align:center;" data-v-7869744c>❌</td></tr></tbody></table><blockquote data-v-7869744c><p data-v-7869744c><strong data-v-7869744c>Bottom line:</strong> If you run a Pterodactyl/Docker node or a multi-tenant VPS and want miners, floods, scans, bombs, escapes, abuse tunnels and malware caught and stopped automatically, Protection Plus is purpose-built for the job.</p></blockquote><hr data-v-7869744c><h2 id="next-steps" tabindex="-1" data-v-7869744c>Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;" data-v-7869744c>​</a></h2><ul data-v-7869744c><li data-v-7869744c><strong data-v-7869744c><a href="./getting-started/installation" data-v-7869744c>Installation →</a></strong> — Get running in under a minute.</li><li data-v-7869744c><strong data-v-7869744c><a href="./getting-started/quick-start" data-v-7869744c>Quick Start →</a></strong> — The safe dry-run → arm workflow.</li><li data-v-7869744c><strong data-v-7869744c><a href="./configuration/reference" data-v-7869744c>Configuration Reference →</a></strong> — Every config value explained.</li><li data-v-7869744c><strong data-v-7869744c><a href="./user-guide/cli" data-v-7869744c>CLI Reference →</a></strong> — Every command and flag.</li><li data-v-7869744c><strong data-v-7869744c><a href="./user-guide/detection" data-v-7869744c>How Detection Works →</a></strong> — The industry-standard checks behind each detector.</li><li data-v-7869744c><strong data-v-7869744c><a href="./architecture/overview" data-v-7869744c>Architecture →</a></strong> — Snapshot model, engine, netns, performance.</li></ul><hr data-v-7869744c><div class="footer-note" data-v-7869744c><p data-v-7869744c><strong data-v-7869744c>Developed by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer" data-v-7869744c>AnAverageBeing</a> for <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer" data-v-7869744c>ALTIS TECH SOLUTIONS</a></strong></p><p data-v-7869744c>For hosting operators who&#39;d rather sleep at night. · <code data-v-7869744c>MIT License</code></p></div>',17))])}const A=r(h,[["render",p],["__scopeId","data-v-7869744c"]]);export{k as __pageData,A as default};
